export class PlayerStore{constructor(){this.storageKey="passportQuestProgress",this.listeners=[],this.state={xp:0,coins:0,stamps:[],completedMissions:[],unlockedItems:[]},this.loadState()}loadState(){const s=localStorage.getItem(this.storageKey);if(s)try{this.state=JSON.parse(s)}catch(s){console.error("Failed to load player progress",s)}}saveState(){localStorage.setItem(this.storageKey,JSON.stringify(this.state)),this.notifyListeners()}subscribe(s){return this.listeners.push(s),()=>{this.listeners=this.listeners.filter(e=>e!==s)}}notifyListeners(){this.listeners.forEach(s=>s(this.state))}completeMission(s){if(this.state.completedMissions.includes(s.id))return{success:!1,message:"Mission already completed!"};this.state.completedMissions.push(s.id),this.state.stamps.push(s.stamp),this.state.xp+=s.xp,this.state.coins+=s.coins;const e=this.checkUnlocks();return this.saveState(),{success:!0,mission:s,newUnlocks:e}}checkUnlocks(){const s=[],e=this.state.stamps.length;return[{required:3,reward:"Traveler Badge"},{required:5,reward:"Traditional Outfit"},{required:10,reward:"Golden Passport"},{required:15,reward:"Explorer Avatar"}].forEach(t=>{e>=t.required&&(this.state.unlockedItems.includes(t.reward)||(this.state.unlockedItems.push(t.reward),s.push(t.reward)))}),s}}export const playerStore=new PlayerStore;